text:
{
  "logline": "閉山の年の沢渡町役場支所で、前任記録係の梶原頼子は下書きの頁を切り取って閲覧簿の裏表紙の袋に残す。",
  "acts": [
    {
      "id": "setup_and_close",
      "chapters": [
        "ch01"
      ],
      "question": "命じられた零の清書の裏で、下書きの頁をどこへ残すのか。"
    }
  ],
  "turns": [
    {
      "id": "t1",
      "chapter": "ch01",
      "choice_ja": "頼子は抗議せずに新しい用紙を出し、死者の欄に零と清書して支所長の検印を受ける。",
      "point_of_no_return": "検印が押された時点で、本欄の零は公文書として確定する。"
    },
    {
      "id": "t2",
      "chapter": "ch01",
      "choice_ja": "頼子は火鉢に白紙の端だけをくべ、下書きの頁に竹の定規を当てて切り取る。",
      "point_of_no_return": "切り取った紙の端が綴じ代に残った時点で、元の頁には戻せない。"
    },
    {
      "id": "t3",
      "chapter": "ch01",
      "choice_ja": "頼子は切り取った下書きを二つに折り、閲覧簿の裏表紙の袋へ挟んで書庫の棚へ戻す。",
      "point_of_no_return": "書庫の鍵を閉めた時点で、次に袋を開けるのは後任の記録係になる。"
    }
  ],
  "subplots": [
    {
      "id": "ash",
      "beats": [
        "起動: 黒田が火鉢で古い紙を焼くよう命じる",
        "干渉: 頼子が白紙の端を燃やして煙と灰を作る",
        "決着: 切り取った本紙は無傷のまま裏表紙の袋へ収まる"
      ],
      "converges": "一章の終盤、火鉢の灰と裏表紙の控えが対になって夜の支所に残る。"
    }
  ],
  "ending": {
    "kind": "open",
    "summary": "閉山記録の本欄は零のまま綴じられ、切り取った下書きの頁は閲覧簿の裏表紙の袋に収められて書庫の棚へ戻る。",
    "aftertaste_ja": "冷えた火鉢の白い灰と、裏表紙の袋のわずかな厚み。"
  },
  "unresolved": [
    {
      "item": "裏表紙の袋の控えを誰が最初に開けるかは、十五年後の本編に委ねられる",
      "foreshadowing": "fs-101",
      "intentional": true
    }
  ]
}
